import type { StoredObject } from "@stallion/client-store";
import {
  type BBox,
  fromTileLocal,
  nativeLevel,
  type Point,
  place,
  TILE_SIZE,
  type Tile,
  toTileLocal,
} from "@stallion/geometry";
import {
  MAX_WIDTH,
  MIN_WIDTH,
  nearestColour,
  nearestSize,
  PALETTE_RGB,
  type PencilSize,
  rgbHex,
  type Stroke,
  type Point as StrokePoint,
  type StrokeStyle,
  styleOf,
  widthOf,
} from "@stallion/schema";
import getStroke, { type StrokeOptions } from "perfect-freehand";

export const PALETTE: readonly string[] = PALETTE_RGB.map(rgbHex);

export const PENCIL_SIZES: readonly PencilSize[] = ["Small", "Medium", "Large"];

export const WIDTH_PRESETS: readonly number[] = [0.5, 1, 2, 40, 60, 96];

export const WIDTH_SLIDER_STEPS = 100;

const WIDTH_SPAN = Math.log(MAX_WIDTH / MIN_WIDTH);

const roundWidth = (width: number): number =>
  width < 4 ? Math.round(width * 2) / 2 : Math.round(width);

export const clampWidth = (width: number): number =>
  Math.min(MAX_WIDTH, Math.max(MIN_WIDTH, roundWidth(width)));

export const sliderToWidth = (step: number): number =>
  clampWidth(MIN_WIDTH * Math.exp((step / WIDTH_SLIDER_STEPS) * WIDTH_SPAN));

export const widthToSlider = (width: number): number =>
  Math.round((Math.log(clampWidth(width) / MIN_WIDTH) / WIDTH_SPAN) * WIDTH_SLIDER_STEPS);

export const MAX_POINTS = 4096;

export const strokeWorldWidth = (width: number, nativeZoom: number): number =>
  width * 2 ** (nativeZoom - 0.5);

const strokeOptions = (size: number, last: boolean): StrokeOptions => ({
  size,
  thinning: 0.5,
  smoothing: 0.5,
  streamline: 0.4,
  simulatePressure: false,
  last,
});

export const HIGHLIGHTER_ALPHA = 0.4;

export const UNIFORM_PRESSURE = 0.5;

export const outlinePath = (
  points: readonly StrokePoint[],
  size: number,
  last: boolean,
): Path2D => {
  const outline = getStroke([...points], strokeOptions(size, last));
  const path = new Path2D();
  const [first, ...rest] = outline;
  if (!first) return path;
  path.moveTo(first[0], first[1]);
  for (const [x, y] of rest) path.lineTo(x, y);
  path.closePath();
  return path;
};

const centrelinePath = (points: readonly StrokePoint[]): Path2D => {
  const path = new Path2D();
  const [first, ...rest] = points;
  if (!first) return path;
  path.moveTo(first[0], first[1]);
  if (rest.length === 0) path.lineTo(first[0], first[1]);
  for (const [x, y] of rest) path.lineTo(x, y);
  return path;
};

export type StrokeInk = { style: StrokeStyle; path: Path2D; lineWidth: number };

export const strokeInk = (
  style: StrokeStyle,
  points: readonly StrokePoint[],
  size: number,
  last: boolean,
): StrokeInk => {
  if (style === "Dashed") return { style, path: centrelinePath(points), lineWidth: size };
  const pressed =
    style === "Uniform" ? points.map(([x, y]): StrokePoint => [x, y, UNIFORM_PRESSURE]) : points;
  return { style, path: outlinePath(pressed, size, last), lineWidth: size };
};

export const dashPattern = (lineWidth: number): number[] => [lineWidth, lineWidth * 2.5];

export const paintInk = (
  ctx: CanvasRenderingContext2D,
  ink: StrokeInk,
  colour: string,
  alpha = 1,
): void => {
  const highlighter = ink.style === "Highlighter";
  ctx.globalAlpha = highlighter ? alpha * HIGHLIGHTER_ALPHA : alpha;
  if (highlighter) ctx.globalCompositeOperation = "multiply";
  if (ink.style === "Dashed") {
    ctx.strokeStyle = colour;
    ctx.lineWidth = ink.lineWidth;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.setLineDash(dashPattern(ink.lineWidth));
    ctx.stroke(ink.path);
    ctx.setLineDash([]);
  } else {
    ctx.fillStyle = colour;
    ctx.fill(ink.path);
  }
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
};

const randomHex = (bytes: number): string =>
  Array.from(crypto.getRandomValues(new Uint8Array(bytes)), (byte) =>
    byte.toString(16).padStart(2, "0"),
  ).join("");

const newObjectId = (): string => `${Date.now().toString(36).padStart(9, "0")}${randomHex(6)}`;

export type Draft = {
  objectId: string;
  rgb: number;
  width: number;
  style: StrokeStyle;
  nativeZoom: number;
  points: StrokePoint[];
};

export const startDraft = (
  rgb: number,
  width: number,
  style: StrokeStyle,
  zoom: number,
): Draft => ({
  objectId: newObjectId(),
  rgb,
  width,
  style,
  nativeZoom: nativeLevel(zoom),
  points: [],
});

export const continueDraft = (draft: Draft): Draft => {
  const last = draft.points.at(-1);
  return { ...draft, objectId: newObjectId(), points: last ? [last] : [] };
};

const draftBounds = (draft: Draft): BBox => {
  const margin = strokeWorldWidth(draft.width, draft.nativeZoom);
  const xs = draft.points.map((p) => p[0]);
  const ys = draft.points.map((p) => p[1]);
  return {
    minX: Math.min(...xs) - margin,
    minY: Math.min(...ys) - margin,
    maxX: Math.max(...xs) + margin,
    maxY: Math.max(...ys) + margin,
  };
};

export const finishDraft = (draft: Draft): StoredObject | undefined => {
  if (draft.points.length === 0) return undefined;
  const bbox = draftBounds(draft);
  const placed = place(bbox);
  if (!placed.ok) return undefined;
  const { tile } = placed;
  const stroke: Stroke = {
    type: "Stroke",
    objectId: draft.objectId,
    nativeZoom: draft.nativeZoom,
    bbox,
    colour: nearestColour(draft.rgb),
    rgb: draft.rgb,
    size: nearestSize(draft.width),
    width: draft.width,
    style: draft.style,
    points: draft.points.map(([x, y, pressure]) => {
      const local = toTileLocal(tile, { x, y });
      return [local.x, local.y, pressure];
    }),
  };
  return { tile, object: stroke };
};

export type StrokeFrame = { origin: Point; scale: number; points: StrokePoint[] };

// Path2D keeps float32, so points live relative to the stroke bbox, never the tile.
export const strokeFrame = (tile: Tile, stroke: Stroke): StrokeFrame => {
  const { bbox } = stroke;
  const origin = { x: bbox.minX, y: bbox.minY };
  const extent = Math.max(
    bbox.maxX - bbox.minX,
    bbox.maxY - bbox.minY,
    strokeWorldWidth(widthOf(stroke), stroke.nativeZoom),
  );
  const scale = extent / TILE_SIZE;
  const points = stroke.points.map(([x, y, pressure]): StrokePoint => {
    const world = fromTileLocal(tile, { x, y });
    return [(world.x - origin.x) / scale, (world.y - origin.y) / scale, pressure];
  });
  return { origin, scale, points };
};

export const strokeFrameInk = (stroke: Stroke, frame: StrokeFrame): StrokeInk =>
  strokeInk(
    styleOf(stroke),
    frame.points,
    strokeWorldWidth(widthOf(stroke), stroke.nativeZoom) / frame.scale,
    true,
  );

export const draftScreenInk = (
  draft: Pick<Draft, "width" | "style" | "nativeZoom" | "points">,
  toScreen: (world: Point) => Point,
  zoom: number,
): StrokeInk =>
  strokeInk(
    draft.style,
    draft.points.map(([x, y, pressure]) => {
      const screen = toScreen({ x, y });
      return [screen.x, screen.y, pressure];
    }),
    strokeWorldWidth(draft.width, draft.nativeZoom) * zoom,
    false,
  );

export const translateStroke = (
  tile: Tile,
  stroke: Stroke,
  dx: number,
  dy: number,
): StoredObject | undefined => {
  const bbox = {
    minX: stroke.bbox.minX + dx,
    minY: stroke.bbox.minY + dy,
    maxX: stroke.bbox.maxX + dx,
    maxY: stroke.bbox.maxY + dy,
  };
  const placed = place(bbox);
  if (!placed.ok) return undefined;
  const points = stroke.points.map(([x, y, pressure]): StrokePoint => {
    const world = fromTileLocal(tile, { x, y });
    const local = toTileLocal(placed.tile, { x: world.x + dx, y: world.y + dy });
    return [local.x, local.y, pressure];
  });
  return { tile: placed.tile, object: { ...stroke, bbox, points } };
};
import { type BBox, contains, fromTileLocal, type Point, type Tile } from "@stallion/geometry";
import { type Stroke, widthOf } from "@stallion/schema";
import { strokeWorldWidth } from "./stroke";

export const ERASER_TOLERANCE_PX = 8;

const segmentDistance = (p: Point, a: Point, b: Point): number => {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const lengthSquared = dx * dx + dy * dy;
  const t =
    lengthSquared === 0
      ? 0
      : Math.max(0, Math.min(1, ((p.x - a.x) * dx + (p.y - a.y) * dy) / lengthSquared));
  return Math.hypot(p.x - (a.x + t * dx), p.y - (a.y + t * dy));
};

const pointBox = ({ x, y }: Point): BBox => ({ minX: x, minY: y, maxX: x, maxY: y });

const grow = (bbox: BBox, margin: number): BBox => ({
  minX: bbox.minX - margin,
  minY: bbox.minY - margin,
  maxX: bbox.maxX + margin,
  maxY: bbox.maxY + margin,
});

export const hitsStroke = (tile: Tile, stroke: Stroke, world: Point, zoom: number): boolean => {
  const reachPx =
    ERASER_TOLERANCE_PX + (strokeWorldWidth(widthOf(stroke), stroke.nativeZoom) * zoom) / 2;
  if (!contains(grow(stroke.bbox, reachPx / zoom), pointBox(world))) return false;
  const screen = stroke.points.map(([x, y]) => {
    const point = fromTileLocal(tile, { x, y });
    return { x: (point.x - world.x) * zoom, y: (point.y - world.y) * zoom };
  });
  const origin = { x: 0, y: 0 };
  const [first] = screen;
  if (!first) return false;
  if (screen.length === 1) return Math.hypot(first.x, first.y) <= reachPx;
  return screen.some((point, index) => {
    const next = screen[index + 1];
    return next !== undefined && segmentDistance(origin, point, next) <= reachPx;
  });
};
export const TILE_SIZE = 256;
export const MIN_LEVEL = -40;
export const MAX_LEVEL = 40;
export const LIVE_TILE_MIN_PX = 64;
export const SUB_PIXEL_PX = 1;
import fc from "fast-check";
import { describe, expect, test } from "vitest";
import {
  contains,
  cull,
  dedupeMarkers,
  fromTileLocal,
  isSubPixel,
  MARKER_PX,
  MAX_LEVEL,
  MIN_LEVEL,
  nativeLevel,
  place,
  tileBounds,
  tileKey,
  tileScreenSize,
  toTileLocal,
  viewTiles,
} from "./index";

const bbox = (minX: number, minY: number, w: number, h: number) => ({
  minX,
  minY,
  maxX: minX + w,
  maxY: minY + h,
});

describe("tiles", () => {
  test("native tiles are between 256 and 512 px on screen", () => {
    for (const zoom of [1, 0.3, 3, 2 ** -20, 1000]) {
      const px = tileScreenSize(nativeLevel(zoom), zoom);
      expect(px).toBeGreaterThanOrEqual(256);
      expect(px).toBeLessThan(512);
    }
  });

  test("native level clamps to the level range", () => {
    expect(nativeLevel(2 ** 60)).toBe(MIN_LEVEL);
    expect(nativeLevel(2 ** -60)).toBe(MAX_LEVEL);
  });

  test("keys and tile-local coordinates round-trip", () => {
    const tile = { level: -3, tx: -5, ty: 7 };
    expect(tileKey(tile)).toBe("-3:-5:7");
    const point = { x: -155, y: 230 };
    expect(fromTileLocal(tile, toTileLocal(tile, point))).toEqual(point);
  });
});

describe("placement", () => {
  test("uses the smallest tile that fits", () => {
    expect(place(bbox(10, 10, 100, 100))).toEqual({ ok: true, tile: { level: -1, tx: 0, ty: 0 } });
  });

  test("bumps a bbox that straddles a boundary to a coarser level", () => {
    const placed = place(bbox(250, 10, 10, 10));
    expect(placed).toEqual({ ok: true, tile: { level: 1, tx: 0, ty: 0 } });
  });

  test("places a bbox across the origin in the root tile", () => {
    expect(place(bbox(-1, -1, 2, 2))).toEqual({
      ok: true,
      tile: { level: MAX_LEVEL, tx: 0, ty: 0 },
    });
  });

  test("the placement tile holds the whole bbox", () => {
    fc.assert(
      fc.property(
        fc.double({ min: -1e9, max: 1e9, noNaN: true }),
        fc.double({ min: -1e9, max: 1e9, noNaN: true }),
        fc.double({ min: 0, max: 1e6, noNaN: true }),
        fc.double({ min: 0, max: 1e6, noNaN: true }),
        (x, y, w, h) => {
          const box = bbox(x, y, w, h);
          const placed = place(box);
          return placed.ok && contains(tileBounds(placed.tile), box);
        },
      ),
    );
  });

  test("the coarser bump terminates within the level range", () => {
    fc.assert(
      fc.property(
        fc.double({ min: -1e300, max: 1e300, noNaN: true }),
        fc.double({ min: -1e300, max: 1e300, noNaN: true }),
        fc.double({ min: 0, max: 1e300, noNaN: true }),
        (x, y, w) => {
          const placed = place(bbox(x, y, w, w));
          return !placed.ok || placed.tile.level <= MAX_LEVEL;
        },
      ),
    );
  });
});

describe("view", () => {
  const zoom = 1;
  const view = viewTiles({ minX: 0, minY: 0, maxX: 1024, maxY: 768 }, zoom);

  test("splits levels into a live band and a snapshot band down to the pixel cutoff", () => {
    expect(view.native).toBe(0);
    expect(view.live.at(0)?.level).toBe(MAX_LEVEL);
    expect(view.live.at(-1)?.level).toBe(-2);
    expect(view.snapshot.map((r) => r.level)).toEqual([-3, -4, -5, -6, -7, -8]);
    expect(view.live.find((r) => r.level === 0)).toEqual({
      level: 0,
      minTx: 0,
      minTy: 0,
      maxTx: 4,
      maxTy: 3,
    });
  });

  test("every visible object lands in a queried tile", () => {
    const ranges = [...view.live, ...view.snapshot];
    for (const box of [bbox(1000, 700, 2, 2), bbox(-50, -50, 100, 100), bbox(500, 500, 1e6, 3)]) {
      const placed = place(box);
      if (!placed.ok) throw new Error("placement overflowed");
