import {
  PALETTE_RGB,
  PENCIL_PX,
  parseRgbHex,
  rgbHex,
  STROKE_STYLES,
  type StrokeStyle,
} from "@stallion/schema";
import type { JSX } from "preact";
import { useEffect, useState } from "preact/hooks";
import { LevelChip } from "./level-chip";
import type { Presence } from "./presence";
import { FollowPill, PresenceStrip } from "./presence-strip";
import {
  PENCIL_SIZES,
  sliderToWidth,
  WIDTH_PRESETS,
  WIDTH_SLIDER_STEPS,
  widthToSlider,
} from "./stroke";
import type { SurfaceView, Tool } from "./surface";
import { CONNECTION_LABEL, type Connection } from "./sync";
import {
  type Control,
  expandedAfterPick,
  loadExpanded,
  loadMode,
  loadRecentColours,
  saveExpanded,
  saveMode,
  saveRecentColours,
  saveStyle,
  type ToolbarMode,
  toolbarLayout,
  toolbarRows,
  WIDE_QUERY,
  withRecentColour,
} from "./toolbar-layout";

const DOT_PX = { Small: 4, Medium: 9, Large: 16 } as const;

const STYLE_TITLE: Record<StrokeStyle, string> = {
  Pen: "Pen: pressure-sensitive ink",
  Highlighter: "Highlighter: translucent ink that darkens what it crosses",
  Dashed: "Dashed: an even dashed line",
  Uniform: "Uniform: ink of even width",
};

const STYLE_WAVE = "M3 16c3-6 6-6 9-2s6 4 9-2";

const STYLE_STROKE: Record<Exclude<StrokeStyle, "Pen">, JSX.SVGAttributes<SVGPathElement>> = {
  Highlighter: { "stroke-width": "6", "stroke-opacity": "0.45" },
  Dashed: { "stroke-width": "2", "stroke-linecap": "round", "stroke-dasharray": "2 4" },
  Uniform: { "stroke-width": "2.5", "stroke-linecap": "round" },
};

function StyleIcon({ style }: { style: StrokeStyle }) {
  return (
    <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
      {style === "Pen" ? (
        <path d="M3 16.5c3-7 6-7 9-2.5s6 3.5 9-2.5c-2 7-6 8-9 4s-6-5-9 1z" fill="currentColor" />
      ) : (
        <path d={STYLE_WAVE} fill="none" stroke="currentColor" {...STYLE_STROKE[style]} />
      )}
    </svg>
  );
}

export type HistoryState = { canUndo: boolean; canRedo: boolean };

type ToolbarProps = {
  tool: Tool;
  onChange: (tool: Tool) => void;
  connection: Connection;
  history: HistoryState;
  onUndo: () => void;
  onRedo: () => void;
  view: SurfaceView;
  onLevel: (level: number) => void;
  shareOpen: boolean;
  onShare: () => void;
  presence: Presence;
  onFollow: (clientId: number | undefined) => void;
};

const storage = () => localStorage;

const colourLabel = (rgb: number): string => {
  const index = PALETTE_RGB.indexOf(rgb as (typeof PALETTE_RGB)[number]);
  return index >= 0 ? `Colour ${index + 1}` : `Colour ${rgbHex(rgb)}`;
};

function HexField({ rgb, onPick }: { rgb: number; onPick: (rgb: number) => void }) {
  const [text, setText] = useState(() => rgbHex(rgb));
  const [invalid, setInvalid] = useState(false);
  useEffect(() => {
    setText(rgbHex(rgb));
    setInvalid(false);
  }, [rgb]);
  const commit = () => {
    const parsed = parseRgbHex(text);
    setInvalid(parsed === undefined);
    if (parsed !== undefined) onPick(parsed);
  };
  return (
    <input
      class="hex-field"
      type="text"
      inputMode="text"
      spellcheck={false}
      autocomplete="off"
      maxLength={7}
      aria-label="Hex colour"
      aria-invalid={invalid}
      title={
        invalid ? "Enter a colour as #rrggbb, for example #123456" : "Type a colour as #rrggbb"
      }
      value={text}
      onInput={(event) => setText(event.currentTarget.value)}
      onChange={commit}
      onKeyDown={(event) => {
        if (event.key === "Enter") commit();
      }}
    />
  );
}

const matchesWide = (): boolean => window.matchMedia(WIDE_QUERY).matches;

const useWide = (): boolean => {
  const [wide, setWide] = useState(matchesWide);
  useEffect(() => {
    const query = window.matchMedia(WIDE_QUERY);
    const update = () => setWide(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);
  return wide;
};

function Icon({ d, join }: { d: string; join?: boolean }) {
  return (
    <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
      <path
        d={d}
        fill="none"
        stroke="currentColor"
        stroke-width="2"
        stroke-linecap="round"
        stroke-linejoin={join ? "round" : undefined}
      />
    </svg>
  );
}

export function Toolbar({
  tool,
  onChange,
  connection,
  history,
  onUndo,
  onRedo,
  view,
  onLevel,
  shareOpen,
  onShare,
  presence,
  onFollow,
}: ToolbarProps) {
  const wide = useWide();
  const [expanded, setExpanded] = useState(() => loadExpanded(storage));
  const [mode, setMode] = useState<ToolbarMode>(() => loadMode(storage));
  const [recentColours, setRecentColours] = useState(() => loadRecentColours(storage));
  const layout = toolbarLayout(mode, wide, expanded);
  const palette = layout === "Palette";

  const expand = (next: boolean) => {
    setExpanded(next);
    saveExpanded(storage, next);
  };
  const flip = () => {
    const next = palette ? "Quick" : "Palette";
    setMode(next);
    saveMode(storage, next);
  };
  const pick = (next: Tool) => {
    onChange(next);
    if (palette) return;
    const after = expandedAfterPick(wide, expanded);
    if (after !== expanded) expand(after);
  };
  const pickCustom = (rgb: number, slot: "primary" | "secondary" = "primary") => {
    const next = withRecentColour(recentColours, rgb);
    setRecentColours(next);
    saveRecentColours(storage, next);
    pick({ ...tool, [slot]: rgb, mode: "Pencil" });
  };
  const pickStyle = (style: StrokeStyle) => {
    saveStyle(storage, style);
    pick({ ...tool, style, mode: "Pencil" });
  };
  const toggleMode = (mode: Tool["mode"]) =>
    pick({ ...tool, mode: tool.mode === mode ? "Pencil" : mode });

  const controls: Record<Control, () => JSX.Element> = {
    Sizes: () => (
      <fieldset key="Sizes" class="group" aria-label="Pencil size">
        {PENCIL_SIZES.map((size) => (
          <button
            key={size}
            type="button"
            aria-pressed={tool.mode === "Pencil" && tool.width === PENCIL_PX[size]}
            aria-label={`${size} pencil`}
            class="tool"
            onClick={() => pick({ ...tool, width: PENCIL_PX[size], mode: "Pencil" })}
          >
            <span class="dot" style={{ width: DOT_PX[size], height: DOT_PX[size] }} />
          </button>
        ))}
      </fieldset>
    ),
    Width: () => (
      <fieldset key="Width" class="group width" aria-label="Stroke width">
        {WIDTH_PRESETS.map((width) => (
          <button
            key={width}
            type="button"
            aria-pressed={tool.mode === "Pencil" && tool.width === width}
            aria-label={`${width} px pencil`}
            class="tool width-preset"
            onClick={() => pick({ ...tool, width, mode: "Pencil" })}
          >
            {width}
          </button>
        ))}
        <input
          class="width-slider"
          type="range"
          min={0}
          max={WIDTH_SLIDER_STEPS}
          step={1}
          aria-label="Stroke width"
          aria-valuetext={`${tool.width} px`}
          value={widthToSlider(tool.width)}
          onInput={(event) =>
            onChange({
              ...tool,
              width: sliderToWidth(Number(event.currentTarget.value)),
              mode: "Pencil",
            })
          }
        />
        <output class="width-value" aria-live="polite">
          {tool.width} px
        </output>
      </fieldset>
    ),
    Styles: () => (
      <fieldset key="Styles" class="group" aria-label="Stroke style">
        {STROKE_STYLES.map((style) => (
          <button
            key={style}
            type="button"
            aria-pressed={tool.mode === "Pencil" && tool.style === style}
            aria-label={`${style} style`}
            title={STYLE_TITLE[style]}
            class="tool"
            data-stroke-style={style}
            onClick={() => pickStyle(style)}
          >
            <StyleIcon style={style} />
          </button>
        ))}
      </fieldset>
    ),
    Colours: () => (
      <fieldset key="Colours" class="group" aria-label="Colour">
        {PALETTE_RGB.map((rgb, index) => (
          <button
            key={rgb}
            type="button"
            aria-pressed={tool.primary === rgb}
            aria-label={`Colour ${index + 1}`}
            title="Tap for primary, right-click or long-press for secondary"
            class={tool.secondary === rgb ? "tool swatch secondary" : "tool swatch"}
            onClick={() => pick({ ...tool, primary: rgb })}
            onContextMenu={(event) => {
              event.preventDefault();
              pick({ ...tool, secondary: rgb });
            }}
          >
            <span class="swatch-fill" style={{ background: rgbHex(rgb) }} />
          </button>
        ))}
      </fieldset>
    ),
    CustomColour: () => (
      <fieldset key="CustomColour" class="group custom-colour" aria-label="Custom colour">
        <label class="tool swatch picker" title="Pick any colour">
          <span class="swatch-fill" />
          <input
            type="color"
            aria-label="Pick a colour"
            value={rgbHex(tool.primary)}
            onChange={(event) => {
              const rgb = parseRgbHex(event.currentTarget.value);
              if (rgb !== undefined) pickCustom(rgb);
            }}
          />
        </label>
        <HexField rgb={tool.primary} onPick={(rgb) => pickCustom(rgb)} />
      </fieldset>
    ),
    RecentColours: () =>
      recentColours.length === 0 ? (
        <span key="RecentColours" hidden />
      ) : (
        <fieldset key="RecentColours" class="group" aria-label="Recent colours">
          {recentColours.map((rgb) => (
            <button
              key={rgb}
              type="button"
              aria-pressed={tool.primary === rgb}
              aria-label={`Recent colour ${rgbHex(rgb)}`}
              title="Tap for primary, right-click or long-press for secondary"
              class={tool.secondary === rgb ? "tool swatch secondary" : "tool swatch"}
              onClick={() => pickCustom(rgb)}
              onContextMenu={(event) => {
                event.preventDefault();
                pickCustom(rgb, "secondary");
              }}
            >
              <span class="swatch-fill" style={{ background: rgbHex(rgb) }} />
            </button>
          ))}
        </fieldset>
      ),
    CurrentColour: () => (
      <button
        key="CurrentColour"
        type="button"
        class="tool swatch current"
        aria-label={`${colourLabel(tool.primary)}, show colours`}
        title="Show sizes and colours"
        onClick={() => expand(!expanded)}
      >
        <span class="swatch-fill" style={{ background: rgbHex(tool.primary) }} />
      </button>
    ),
    Pencil: () => (
      <button
        key="Pencil"
        type="button"
        class="tool"
        aria-pressed={tool.mode === "Pencil"}
        aria-label={`${tool.style} pencil, ${tool.width} px`}
        title="Draw"
        onClick={() => pick({ ...tool, mode: "Pencil" })}
      >
        <Icon d="M4 20l1-5L16 4l4 4L9 19l-5 1zM14 6l4 4" join />
      </button>
    ),
    Pan: () => (
      <button
        key="Pan"
        type="button"
        class="tool"
        aria-pressed={tool.mode === "Pan"}
        aria-label="Pan tool"
        title="Drag with one finger to move the board"
        onClick={() => toggleMode("Pan")}
      >
        <Icon d="M12 2v20M2 12h20M12 2l-3 3M12 2l3 3M12 22l-3-3M12 22l3-3M2 12l3-3M2 12l3 3M22 12l-3-3M22 12l-3 3" />
      </button>
    ),
    Select: () => (
      <button
        key="Select"
