  return Math.hypot(px - a * tx, py - b * ty);
}

export function insideEllipse(p: Point, centre: Point, rx: number, ry: number): boolean {
  if (rx === 0 || ry === 0) return false;
  return ((p.x - centre.x) / rx) ** 2 + ((p.y - centre.y) / ry) ** 2 <= 1;
}
