    ctx.beginPath();
    ctx.moveTo(end.x, end.y);
    ctx.lineTo(bx + wing.x, by + wing.y);
    ctx.lineTo(bx - wing.x, by - wing.y);
    ctx.closePath();
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
};
